INSERT INTO recipes (id, name, slug, description, instructions, image_url, preparation_time_minutes, cooking_time_minutes, difficulty, servings, is_vegetarian, is_vegan, is_egg_free, is_dairy_free, category) VALUES
(1, 'Aloo Jeera', 'aloo-jeera', 'A simple potato dish with cumin and warm spices.', 'Wash and cube the potatoes.\nHeat oil and add cumin seeds.\nAdd potatoes, turmeric, and a little salt.\nCook until golden and tender.\nFinish with lemon and coriander.', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=900&q=80', 10, 20, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Vegetable'),
(2, 'Aloo Gobi', 'aloo-gobi', 'Potato and cauliflower tossed with fragrant Indian spices.', 'Heat oil and add cumin and turmeric.\nAdd chopped cauliflower and potato.\nCook with ginger, garlic, and spices.\nCover until tender and serve warm.', 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=900&q=80', 15, 25, 'Medium', 3, TRUE, TRUE, TRUE, TRUE, 'Vegetable'),
(3, 'Tomato Rice', 'tomato-rice', 'Comforting tomato rice with garlic and spices.', 'Cook rice and cool slightly.\nSauté onions, garlic, and tomatoes.\nAdd turmeric and cooked rice.\nFinish with herbs and lemon.', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?auto=format&fit=crop&w=900&q=80', 10, 20, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Rice'),
(4, 'Vegetable Pulao', 'vegetable-pulao', 'A fragrant rice dish with colorful vegetables and spices.', 'Sauté onion, ginger, and spices.\nAdd vegetables and rice.\nPour in stock and cook gently.\nServe with fresh coriander.', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?auto=format&fit=crop&w=900&q=80', 15, 30, 'Medium', 3, TRUE, TRUE, TRUE, TRUE, 'Rice'),
(5, 'Masala Omelette', 'masala-omelette', 'A spicy, protein-rich breakfast with vegetables.', 'Whisk eggs and salt.\nAdd onion, tomato, green chili, and coriander.\nCook gently in a pan.\nFold and serve hot.', 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=900&q=80', 10, 10, 'Easy', 2, TRUE, FALSE, FALSE, TRUE, 'Breakfast'),
(6, 'Poha', 'poha', 'Soft flattened rice cooked with onion, peas, and curry leaves.', 'Rinse poha lightly.\nSauté onion, green chili, and curry leaves.\nAdd peas and spices.\nMix in poha and cook until fluffy.', 'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?auto=format&fit=crop&w=900&q=80', 10, 15, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Breakfast'),
(7, 'Upma', 'upma', 'Savory semolina breakfast with vegetables and mustard seeds.', 'Roast semolina lightly.\nTemper mustard, curry leaves, and onion.\nAdd vegetables and water.\nStir in semolina until thick.', 'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?auto=format&fit=crop&w=900&q=80', 10, 20, 'Medium', 2, TRUE, TRUE, TRUE, TRUE, 'Breakfast'),
(8, 'Dal Tadka', 'dal-tadka', 'Yellow lentil curry with onion-tomato tempering.', 'Cook lentils until soft.\nPrepare tadka with cumin, garlic, onion, and tomato.\nAdd tempering to lentils.\nFinish with coriander and lemon.', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=900&q=80', 15, 30, 'Medium', 3, TRUE, TRUE, TRUE, TRUE, 'Lentil'),
(9, 'Chana Masala', 'chana-masala', 'Chickpea curry with tomatoes, onion, and warming spices.', 'Sauté onion, ginger, garlic, and tomato.\nAdd chickpeas and spices.\nSimmer until thick and fragrant.\nServe with rice or bread.', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=900&q=80', 20, 25, 'Medium', 3, TRUE, TRUE, TRUE, TRUE, 'Curry'),
(10, 'Vegetable Fried Rice', 'vegetable-fried-rice', 'A quick rice stir-fry with mixed vegetables and soy sauce.', 'Cook rice and chill slightly.\nStir-fry onion, carrots, peas, and peppers.\nAdd rice and soy sauce.\nFinish with spring onion and sesame.', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?auto=format&fit=crop&w=900&q=80', 15, 15, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Rice'),
(11, 'Tomato Pasta', 'tomato-pasta', 'Classic tomato pasta enriched with garlic and basil.', 'Boil pasta until tender.\nSauté garlic and onion.\nAdd tomato sauce, basil, and pepper.\nToss with pasta and serve.', 'https://images.unsplash.com/photo-1555949258-eb67b1ef0ceb?auto=format&fit=crop&w=900&q=80', 10, 20, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Pasta'),
(12, 'Potato Sandwich', 'potato-sandwich', 'Crisp potato slices and spices in a sandwich.', 'Boil potatoes and slice thin.\nSeason with chaat masala, chili, and lemon.\nLayer between bread with onion and tomato.\nToast lightly.', 'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=900&q=80', 15, 10, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Snack'),
(13, 'Paneer Bhurji', 'paneer-bhurji', 'Crumbled paneer sautéed with onion, tomato, and spices.', 'Crumbly paneer and set aside.\nCook onion, tomato, and chili.\nAdd paneer and masala.\nServe hot with bread.', 'https://images.unsplash.com/photo-1631452180519-c014fe946bc7?auto=format&fit=crop&w=900&q=80', 10, 15, 'Easy', 2, TRUE, FALSE, TRUE, FALSE, 'Curry'),
(14, 'Vegetable Soup', 'vegetable-soup', 'A nourishing soup with carrots, celery, and herbs.', 'Sauté onion and garlic.\nAdd vegetables and stock.\nSimmer until tender.\nBlend partly for a creamy texture.', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=900&q=80', 15, 25, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Soup'),
(15, 'Chickpea Salad', 'chickpea-salad', 'Fresh salad with lemon, cucumber, and herbs.', 'Mix chickpeas with cucumber, tomato, onion, and lemon.\nAdd coriander and olive oil.\nSeason with pepper and salt.\nServe chilled.', 'https://images.unsplash.com/photo-1546793665-c74683f339c1?auto=format&fit=crop&w=900&q=80', 15, 0, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Salad'),
(16, 'Tomato Soup', 'tomato-soup', 'Smooth and warming tomato soup with basil.', 'Sauté onion and garlic.\nAdd tomato and stock.\nSimmer and blend until smooth.\nFinish with basil and cream optional.', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=900&q=80', 10, 25, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Soup'),
(17, 'Paneer Tikka Wrap', 'paneer-tikka-wrap', 'Grilled paneer with vegetables and yogurt marinade.', 'Marinate paneer with yogurt and spices.\nSear until golden.\nFill wraps with onion, tomato, and lettuce.\nServe with sauce.', 'https://images.unsplash.com/photo-1617093727343-374698b1b08d?auto=format&fit=crop&w=900&q=80', 20, 20, 'Medium', 2, TRUE, FALSE, TRUE, FALSE, 'Wrap'),
(18, 'Vegetable Khichdi', 'vegetable-khichdi', 'Simple rice and lentil comfort bowl.', 'Cook rice and lentils together.\nAdd vegetables, cumin, and turmeric.\nSimmer gently until soft.\nFinish with lemon and ghee optional.', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?auto=format&fit=crop&w=900&q=80', 15, 25, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Rice'),
(19, 'Mushroom Curry', 'mushroom-curry', 'Earthy mushrooms in bold onion-tomato gravy.', 'Sauté onion, garlic, and ginger.\nAdd mushrooms and spices.\nAdd tomato and simmer.\nServe with rice or bread.', 'https://images.unsplash.com/photo-1518843875459-f738682238a6?auto=format&fit=crop&w=900&q=80', 15, 20, 'Medium', 2, TRUE, TRUE, TRUE, TRUE, 'Curry'),
(20, 'Lemon Rice', 'lemon-rice', 'Tangy rice with turmeric, peanuts, and curry leaves.', 'Cook rice.\nTemper mustard seeds, curry leaves, and peanuts.\nAdd lemon juice and turmeric.\nMix with rice and serve with cucumber.', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?auto=format&fit=crop&w=900&q=80', 10, 15, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Rice'),
(21, 'Vegetable Stir Fry', 'vegetable-stir-fry', 'A fast stir-fry of colorful healthy vegetables.', 'Heat oil in a wok.\nStir-fry onion, carrot, pepper, and broccoli.\nAdd soy sauce and ginger.\nFinish with sesame and spring onion.', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=900&q=80', 10, 15, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Vegetable'),
(22, 'Pasta Primavera', 'pasta-primavera', 'Fresh garden vegetables with olive oil pasta.', 'Boil pasta until just tender.\nSauté zucchini, peas, broccoli, and garlic.\nToss with pasta, olive oil, and basil.\nServe warm.', 'https://images.unsplash.com/photo-1555949258-eb67b1ef0ceb?auto=format&fit=crop&w=900&q=80', 15, 20, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Pasta'),
(23, 'Khichdi Bowl', 'khichdi-bowl', 'Comforting rice and lentil bowl with vegetables.', 'Cook rice and lentils together.\nAdd onion, tomato, turmeric, and cumin.\nSimmer until thick and soft.\nServe with yogurt or pickle.', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?auto=format&fit=crop&w=900&q=80', 15, 25, 'Easy', 2, TRUE, TRUE, TRUE, TRUE, 'Rice'),
(24, 'Coconut Lentil Curry', 'coconut-lentil-curry', 'Velvety lentils cooked in coconut milk.', 'Sauté onion, garlic, and spices.\nAdd lentils and coconut milk.\nSimmer until creamy and tender.\nFinish with lime and cilantro.', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=900&q=80', 15, 30, 'Medium', 3, TRUE, TRUE, TRUE, TRUE, 'Curry'),
(25, 'Vegetable Quesadilla', 'vegetable-quesadilla', 'Quick tortilla filling with vegetables and melted cheese.', 'Sauté peppers, onion, and spinach.\nAdd cheese and place between tortillas.\nToast until crisp and melted.\nServe with salsa.', 'https://images.unsplash.com/photo-1552332386-f8dd00dc2f85?auto=format&fit=crop&w=900&q=80', 15, 15, 'Easy', 2, TRUE, FALSE, TRUE, FALSE, 'Wrap');
